     "clue": "압록강 가까운 산꼭대기에 쌓은 성이에요. 고구려의 첫 도읍이 있던 곳이에요.",
     "exp": "지금의 중국 랴오닝성 환런(환인)에 있는 산성으로, 졸본성 또는 홀승골성이라고도 불러요. 『삼국사기』에는 기원전 37년 주몽(동명성왕)이 이곳에 고구려를 세우고 도읍했다고 전해요. 광개토태왕릉비에도 시조 추모왕이 ‘홀본의 서성산 위’에 도읍을 정했다는 내용이 있어요. 서기 3년 유리왕이 도읍을 국내성으로 옮길 때까지 고구려의 도읍이었어요. 이 산성을 포함한 고구려 유적은 2004년 유네스코 세계유산이 되었어요.",
