     "ill": 32,
     "short": "금관과 천마도가 나온 신라 왕족의 큰 무덤떼",
     "clue": "경북 경주 시내에 둥근 큰 무덤들이 모여 있어요. 한 무덤에서 하늘을 나는 말 그림과 금관이 나왔어요.",
     "exp": "경북 경주 시내에 있는 신라 왕과 왕비, 귀족의 것으로 보이는 큰 무덤 23기가 모인 곳이에요(사적). 4~6세기에 만든 돌무지덧널무덤, 곧 나무방 위에 돌을 쌓고 흙으로 덮은 무덤이에요. 그중 천마총은 1973년에 발굴됐는데, 말 안장 가리개(말다래)에 그려진 하늘을 나는 말 그림, 곧 천마도가 나와서 이름이 붙었어요. 금관, 금 허리띠, 금귀걸이 같은 황금 장신구도 나왔어요. 천마총은 5세기 말~6세기 초에 만든 것으로 보이고, 누가 묻혔는지는 학자마다 의견이 달라요.",
