     "exp": "서울에 있는 조선의 으뜸 궁궐(법궁)이에요. 조선을 세운 뒤 1395년에 지었고, 이름 \"경복\"에는 새 나라가 큰 복을 누리며 번영하기를 바라는 뜻이 담겨 있어요. 세종 때 이곳에서 훈민정음(한글)이 만들어지고 알려졌어요. 1592년 임진왜란 때 불탄 뒤 270여 년 동안 다시 짓지 못하다가 1867년 흥선대원군 때 다시 지었어요. 신하들과 나라의 큰 행사를 하던 근정전이 가장 중요한 건물이에요. 일제강점기에 많은 건물이 헐리고 가려졌다가 1990년대부터 복원하고 있어요.",
