     "exp": "서울에 있는 조선 왕실의 사당으로, 돌아가신 왕과 왕비의 신주(위패)를 모시고 제사를 지내는 곳이에요. 조선을 세운 뒤 1395년 태조 때 경복궁 왼쪽에 세웠고, \"왼쪽에 종묘, 오른쪽에 사직\"이라는 원칙을 따랐어요. 임진왜란 때 불탄 뒤 1608년에 다시 지었어요. 가장 중요한 건물인 정전(국보)은 일직선으로 길게 이어진 모습이 특징이고, 화려한 장식 없이 소박하고 엄숙해요. 1995년 유네스코 세계유산이 되었고, 종묘제례와 종묘제례악은 2001년 인류무형유산이 되었어요.",
